<?php require_once __DIR__.'/ui.php';use Srms\Application as App;page_heading('Users & access','Provision verified identities and manage access to Trust records.');?><section class="panel"><?php data_table($users,['full_name'=>'Name','role_name'=>'Role','is_active'=>'Active','must_change_password'=>'Password change required','last_login_at'=>'Last login']);?></section><details class="panel form-panel" open><summary>Create user</summary><p>Verify ownership of the phone number before provisioning access. Share the temporary password through a secure channel.</p><?php form_start('user-create');field('full_name','Full name','','text',true);field('role_id','Role','','select',true,App::options('roles'));field('ratepayer_id','Linked ratepayer (Property Owner role only)','','select',false,App::options('ratepayers'));field('phone_number','Verified phone number','','tel',true);field('password','Temporary password','','password',true);submit('Create user');?></details><details class="panel form-panel"><summary>Reset password or change access</summary><?php form_start('user-update');field('id','User','','select',true,array_column($users,'full_name','id'));field('active','Account access','','select',false,['1'=>'Enabled','0'=>'Disabled']);field('password','New temporary password (optional)','','password');submit('Update user');?></details>
